/**
 * Repair feature API client.
 */

import type {
  RepairDetail,
  RepairDetailWithCustomer,
  CustomerWithBicycles,
} from './types.js'

// ---------------------------------------------------------------------------
// Types for request/response shapes
// ---------------------------------------------------------------------------

export interface PaginatedRepairs {
  repairs: RepairDetailWithCustomer[]
  total: number
  page: number
  pageSize: number
  totalPages: number
}

/**
 * Enriched repair detail returned by GET /api/repairs/:id.
 * Mirrors the server's `RepairDetailEnriched` shape:
 *   { repair, customer, bicycle, lineItems, workLogs }
 */
export interface RepairDetailResponse {
  /** Repair header with epoch-ms timestamps and id-only references */
  repair: {
    id: string
    bicycleId: string
    assignedTo: string | null
    status: RepairDetail['status']
    customerNotes: string | null
    internalNotes: string | null
    holdReason: RepairDetail['holdReason']
    holdReasonNote: string | null
    plannedDate: number | null
    pickupDate: number | null
    completedAt: number | null
    createdAt: number
  }
  /** Customer associated with the bicycle (null if customer was deleted) */
  customer?: {
    id: string
    firstName: string | null
    lastName: string | null
    companyName: string | null
    phone: string | null
    email: string | null
  } | null
  /** Bicycle being serviced */
  bicycle: {
    id: string
    brand: string
    model: string
    color: string | null
    year: number | null
  }
  /** Line items (parts and labor) for this repair */
  lineItems: Array<{
    id: string
    repairId: string
    lineType: 'part' | 'labor'
    partId: string | null
    laborServiceId: string | null
    description: string
    quantity: number
    unitPriceNet: number
    vatRateId: string
    discountPercent: number | null
    lineTotalNet: number
    lineTotalVat: number
    lineTotalGross: number
    minutesWorked: number | null
    hourlyRateSnapshot: number | null
    createdAt: number
  }>
  /** Work-log timer sessions (epoch-ms timestamps) */
  workLogs: Array<{
    id: string
    repairId: string
    userId: string
    startedAt: number | null
    endedAt: number | null
    durationMs?: number
  }>
}

interface RepairIntakeInput {
  customerMode: 'existing' | 'new'
  existingCustomerId?: string
  newCustomer?: {
    firstName?: string
    lastName?: string
    companyName?: string
    phone: string
    email?: string
  }
  bicycleMode: 'select_existing' | 'create_new'
  existingBicycleId?: string
  newBicycle?: {
    brand: string
    model: string
    color: string
  }
  customerNotes: string
  plannedDate?: number | null
  pickupDate?: number | null
}

interface StatusTransitionInput {
  targetStatus: RepairDetail['status']
  holdReason?: 'waiting_parts' | 'awaiting_customer_approval' | 'other'
  holdReasonNote?: string
}

interface NotesUpdateInput {
  customerNotes?: string | null
  internalNotes?: string | null
  plannedDate?: number | null
  pickupDate?: number | null
}

// ---------------------------------------------------------------------------
// API Functions
// ---------------------------------------------------------------------------

/** Create a new repair via the intake flow. */
export async function createRepair(input: RepairIntakeInput): Promise<RepairDetail> {
  const response = await fetch('/api/repairs', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to create repair' }))
    throw new Error(error.error || 'Failed to create repair')
  }

  return response.json()
}

/** Get a single repair by ID. Returns the enriched shape (header + customer + bicycle + line items + work logs). */
export async function getRepair(id: string): Promise<RepairDetailResponse> {
  const response = await fetch(`/api/repairs/${id}`)

  if (!response.ok) {
    throw new Error('Failed to fetch repair')
  }

  return response.json()
}

/** Transition a repair's status. */
export async function transitionRepairStatus(id: string, input: StatusTransitionInput): Promise<RepairDetail> {
  const response = await fetch(`/api/repairs/${id}/transition`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to transition status' }))
    throw new Error(error.error || 'Failed to transition status')
  }

  return response.json()
}

/** Update repair notes. */
export async function updateRepairNotes(id: string, input: NotesUpdateInput): Promise<RepairDetail> {
  const response = await fetch(`/api/repairs/${id}/notes`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to update notes' }))
    throw new Error(error.error || 'Failed to update notes')
  }

  return response.json()
}

/** Get a customer with their bicycles for intake selection. */
export async function getCustomerWithBicycles(customerId: string): Promise<CustomerWithBicycles> {
  const response = await fetch(`/api/repairs/customers/${customerId}`)

  if (!response.ok) {
    throw new Error('Failed to fetch customer with bicycles')
  }

  return response.json()
}

// ---------------------------------------------------------------------------
// Timer API — POST /repairs/:id/timer/start & stop
// ---------------------------------------------------------------------------

export interface WorkLog {
  id: string
  repairId: string
  userId: string
  startedAt: number | null
  endedAt: number | null
  durationMs?: number
}

/** Start a manual work timer for a repair. Returns the created work log. */
export async function startWorkTimer(repairId: string, userId: string): Promise<WorkLog> {
  const response = await fetch(`/api/repairs/${repairId}/timer/start`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ userId }),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to start timer' }))
    throw new Error(error.error || 'Failed to start work timer')
  }

  return response.json()
}

/** Stop an active work timer session. Returns the updated work log with duration. */
export async function stopWorkTimer(repairId: string, workLogId: string): Promise<WorkLog> {
  const response = await fetch(`/api/repairs/${repairId}/timer/stop`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ workLogId }),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to stop timer' }))
    throw new Error(error.error || 'Failed to stop work timer')
  }

  return response.json()
}

// ---------------------------------------------------------------------------
// Repair List API — GET /repairs
// ---------------------------------------------------------------------------

interface RepairListFilters {
  status?: string
  assignedTo?: string
  pickupDate?: 'today' | 'this_week'
  page?: number
  pageSize?: number
}

/** Get paginated repair list with optional filters. */
export async function getRepairs(filters: RepairListFilters = {}): Promise<PaginatedRepairs> {
  const params = new URLSearchParams()

  if (filters.status) params.set('status', filters.status)
  if (filters.assignedTo === 'unassigned') params.set('assignedTo', 'unassigned')
  else if (filters.assignedTo) params.set('assignedTo', filters.assignedTo)
  if (filters.pickupDate) params.set('pickupDate', filters.pickupDate)
  params.set('page', String(filters.page ?? 1))
  params.set('pageSize', String(filters.pageSize ?? 20))

  const response = await fetch(`/api/repairs?${params.toString()}`)

  if (!response.ok) {
    throw new Error('Failed to fetch repairs list')
  }

  return response.json()
}

// ---------------------------------------------------------------------------
// Payment Completion API — POST /repairs/:id/complete
// ---------------------------------------------------------------------------

export interface RepairPaymentMethod {
  method: 'cash' | 'card'
  amount: number
}

export interface CompleteRepairInput {
  payments: RepairPaymentMethod[]
}

export interface CompleteRepairResult {
  repair: {
    id: string
    bicycleId: string
    assignedTo: string | null
    status: 'completed'
    customerNotes: string | null
    internalNotes: string | null
    holdReason: string | null
    holdReasonNote: string | null
    plannedDate: number | null
    pickupDate: number | null
    completedAt: number | null
    createdAt: number
  }
  sale: {
    id: string
    saleNumber: string
    customerId: string | null
    sourceType: 'direct_sale' | 'repair' | 'customer_order' | 'backorder'
    sourceId: string | null
    status: 'completed' | 'voided'
    subtotalNet: number
    vatTotal: number
    totalGross: number
  }
  payments: Array<{
    id: string
    method: 'cash' | 'card' | 'bank_transfer'
    amount: number
  }>
  stockMovements: Array<{
    id: string
    partId: string
    quantityDelta: number
    reason: string
    referenceType: string
    referenceId: string
  }>
}

/**
 * Complete a repair with payment data (single or split methods).
 *
 * Atomic transaction: validates → deducts stock → creates linked sale → marks completed.
 */
export async function completeRepairPayment(
  repairId: string,
  input: CompleteRepairInput,
): Promise<CompleteRepairResult> {
  const response = await fetch(`/api/repairs/${repairId}/complete`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Payment completion failed' }))
    throw new Error(error.error || `Failed to complete repair (status ${response.status})`)
  }

  return response.json() as Promise<CompleteRepairResult>
}

// ---------------------------------------------------------------------------
// Week Calendar API — GET /repairs?from=&to=&statusIn=
// ---------------------------------------------------------------------------

/** Active statuses shown on the week calendar */
const ACTIVE_STATUSES = ['in_progress', 'on_hold', 'verified', 'ready'] as const

/**
 * Fetch repairs for a date range (week). Filters by active statuses only.
 *
 * @param from — Inclusive epoch-ms lower bound
 * @param to — Inclusive epoch-ms upper bound
 */
export async function getRepairsForWeek(from: number, to: number): Promise<PaginatedRepairs> {
  const statusIn = ACTIVE_STATUSES.join(',')
  const params = new URLSearchParams()
  params.set('from', String(from))
  params.set('to', String(to))
  params.set('statusIn', statusIn)
  params.set('page', '1')
  params.set('pageSize', '100') // calendar needs all repairs for the week

  const response = await fetch(`/api/repairs?${params.toString()}`)

  if (!response.ok) {
    throw new Error('Failed to fetch repairs for week')
  }

  return response.json()
}

/**
 * Repair feature types — mirrors shared types for frontend use.
 */

// ============================================================================
// Repair Status
// ============================================================================

export type RepairStatus = 'intake' | 'in_progress' | 'on_hold' | 'verified' | 'ready' | 'completed' | 'cancelled'

/** Color mapping for status badges */
export const STATUS_COLORS: Record<RepairStatus, string> = {
  intake: 'bg-blue-100 text-blue-800',
  in_progress: 'bg-yellow-100 text-yellow-800',
  on_hold: 'bg-orange-100 text-orange-800',
  verified: 'bg-purple-100 text-purple-800',
  ready: 'bg-green-100 text-green-800',
  completed: 'bg-gray-100 text-gray-800',
  cancelled: 'bg-red-100 text-red-800',
}

// ============================================================================
// Repair Detail Shape (matches API response)
// ============================================================================

export interface RepairDetail {
  id: string
  bicycleId: string
  assignedTo: string | null
  status: RepairStatus
  customerNotes: string | null
  internalNotes: string | null
  holdReason: 'waiting_parts' | 'awaiting_customer_approval' | 'other' | null
  holdReasonNote: string | null
  plannedDate: number | null
  pickupDate: number | null
  completedAt: number | null
  createdAt: number
}

/** Repair detail enriched with customer name and bicycle info for list display */
export interface RepairDetailWithCustomer extends Omit<RepairDetail, 'bicycleId'> {
  customerName: string | null
  bicycleBrand: string
  bicycleModel: string
  bicycleColor: string | null
}

// ============================================================================
// Intake Form Types
// ============================================================================

/** Customer selection mode */
export type CustomerMode = 'existing' | 'new'

/** Bicycle selection mode */
export type BicycleMode = 'select_existing' | 'create_new'

/** Compact customer shape for selectors — matches GET /api/customers response. */
export interface IntakeCustomer {
  id: string
  displayName: string
  type: 'private' | 'company'
}

/** Compact bicycle shape for selectors */
export interface IntakeBicycle {
  id: string
  brand: string
  model: string
  color: string | null
  year: number | null
}

/** Customer with their bicycles — returned during intake lookup */
export interface CustomerWithBicycles extends IntakeCustomer {
  bicycles: IntakeBicycle[]
}

/** Form data for the repair intake modal */
export interface RepairIntakeFormData {
  // Customer section
  customerMode: CustomerMode
  existingCustomerId?: string
  newFirstName?: string
  newLastName?: string
  newCompanyName?: string
  newPhone: string
  newEmail: string

  // Bicycle section
  bicycleMode: BicycleMode
  existingBicycleId?: string
  newBrand: string
  newModel: string
  newColor: string

  // Notes
  customerNotes: string

  // Optional scheduling dates (epoch ms, nullable)
  plannedDate?: number | null
  pickupDate?: number | null
}

/** Default empty form state */
export const createEmptyIntakeForm = (): RepairIntakeFormData => ({
  customerMode: 'existing',
  newPhone: '',
  newEmail: '',
  bicycleMode: 'select_existing',
  newBrand: '',
  newModel: '',
  newColor: '',
  customerNotes: '',
})

/**
 * Explicit TypeScript interfaces for repair-related entities.
 * Mirrors the DB schema but is decoupled from Drizzle inference.
 * Both client and server import these as single source of truth.
 */

// ============================================================================
// Repair Status — lifecycle states
// ============================================================================

export type RepairStatus = 'intake' | 'in_progress' | 'on_hold' | 'verified' | 'ready' | 'completed' | 'cancelled'

/** Valid status transitions from a given source status */
export const VALID_TRANSITIONS: Record<RepairStatus, RepairStatus[]> = {
  intake: ['in_progress'],
  in_progress: ['on_hold', 'verified'],
  on_hold: ['in_progress'],
  verified: ['ready'],
  ready: ['completed'],
  completed: [], // terminal — no transitions allowed (except via cancel)
  cancelled: [], // terminal
}

/** All statuses that can be reached from any state */
export const CANCEL_TARGETS: RepairStatus[] = [
  'intake', 'in_progress', 'on_hold', 'verified', 'ready'
]

// ============================================================================
// Hold Reason — why a repair is paused
// ============================================================================

export type HoldReason = 'waiting_parts' | 'awaiting_customer_approval' | 'other'

// ============================================================================
// Repair Header
// ============================================================================

/** A repair record representing a bicycle service job */
export interface Repair {
  /** Unique identifier (client-generated UUID) */
  id: string
  /** Bicycle being serviced */
  bicycleId: string
  /** Assigned technician (NULL = unassigned, deferred dispatch) */
  assignedTo: string | null
  /** Current status in the lifecycle */
  status: RepairStatus
  /** Notes visible to customer */
  customerNotes: string | null
  /** Internal technician observations */
  internalNotes: string | null
  /** Reason for being on hold (requires note when set) */
  holdReason: HoldReason | null
  /** Explanation for the hold reason */
  holdReasonNote: string | null
  /** Scheduled start/completion date */
  plannedDate: number | null // epoch ms timestamp
  /** Customer collection date */
  pickupDate: number | null // epoch ms timestamp
  /** When payment was completed */
  completedAt: number | null // epoch ms timestamp
  /** Creation timestamp */
  createdAt: number // epoch ms timestamp
}

// ============================================================================
// Repair Line Item — parts used and labor logged
// ============================================================================

/** Type of line item in a repair */
export type RepairLineItemType = 'part' | 'labor'

/** A line item on a repair (parts or labor) */
export interface RepairLineItem {
  /** Unique identifier */
  id: string
  /** Parent repair ID */
  repairId: string
  /** Type of line item */
  lineType: RepairLineItemType
  /** Reference to part catalog (NULL for labor items) */
  partId: string | null
  /** Reference to labor service catalog (NULL for parts) */
  laborServiceId: string | null
  /** Human-readable description */
  description: string
  /** Quantity (default 1) */
  quantity: number
  /** Unit price ex-tax in cents */
  unitPriceNet: number
  /** VAT rate reference ID */
  vatRateId: string
  /** Discount basis points (nullable = no discount) */
  discountPercent: number | null
  /** Net total after discount */
  lineTotalNet: number
  /** VAT amount */
  lineTotalVat: number
  /** Gross total incl. VAT */
  lineTotalGross: number
  /** Billing minutes worked (for hourly labor) */
  minutesWorked: number | null
  /** Worker's rate at time of logging (hourly services) */
  hourlyRateSnapshot: number | null
  /** Creation timestamp */
  createdAt: number // epoch ms timestamp
}

// ============================================================================
// Work Log — timer session per repair
// ============================================================================

/** A manual work timer session for a repair */
export interface WorkLog {
  /** Unique identifier */
  id: string
  /** Parent repair ID */
  repairId: string
  /** Technician who worked (user ID) */
  userId: string
  /** When the timer started */
  startedAt: number // epoch ms timestamp
  /** When the timer stopped (NULL if still running) */
  endedAt: number | null // epoch ms timestamp
  /** Duration in milliseconds (only when endedAt is set) */
  durationMs?: number
}

// ============================================================================
// Status History — audit trail for transitions
// ============================================================================

/** A single status transition record */
export interface RepairStatusHistory {
  /** Unique identifier */
  id: string
  /** Parent repair ID */
  repairId: string
  /** The status this record represents */
  status: RepairStatus
  /** When the transition occurred */
  transitionedAt: number // epoch ms timestamp
}

// ============================================================================
// Intake Input — combined customer + bicycle + notes for new repairs
// ============================================================================

/** Customer lookup result during intake (compact shape) */
export interface IntakeCustomer {
  id: string
  type: 'private' | 'company'
  firstName: string | null
  lastName: string | null
  companyName: string | null
  phone: string | null
  email: string | null
}

/** Bicycle option during intake (compact shape) */
export interface IntakeBicycle {
  id: string
  brand: string
  model: string
  color: string | null
  year: number | null
}

/** Customer selection mode for intake — 'none' for walk-in without customer */
export type CustomerMode = 'existing' | 'new' | 'none'

/** Bicycle selection mode for intake */
export type BicycleMode = 'select_existing' | 'create_new'

/** Input shape for the repair intake form */
export interface RepairIntakeInput {
  /** Whether selecting existing or creating new customer */
  customerMode: CustomerMode
  /** Existing customer ID (when customerMode='existing') */
  existingCustomerId?: string
  /** New customer data (when customerMode='new') */
  newCustomer?: {
    firstName?: string
    lastName?: string
    companyName?: string
    phone: string
    email: string
  }
  /** Whether selecting existing or creating new bicycle */
  bicycleMode: BicycleMode
  /** Existing bicycle ID (when bicycleMode='select_existing') */
  existingBicycleId?: string
  /** New bicycle data (when bicycleMode='create_new') */
  newBicycle?: {
    brand: string
    model: string
    color: string
  }
  /** Customer-facing notes captured at intake */
  customerNotes: string
  /** Scheduled start/completion date (optional, epoch ms) */
  plannedDate?: number | null
  /** Customer collection/pickup date (optional, epoch ms) */
  pickupDate?: number | null
}

// ============================================================================
// Repair Detail — enriched shape with line items and work logs
// ============================================================================

/** A repair detail response including all related data */
export interface RepairDetail {
  /** The repair header */
  repair: Repair
  /** Customer associated with the bicycle */
  customer?: {
    id: string
    firstName: string | null
    lastName: string | null
    companyName: string | null
    phone: string | null
    email: string | null
  }
  /** Bicycle being serviced */
  bicycle: {
    id: string
    brand: string
    model: string
    color: string | null
    year: number | null
  }
  /** Line items (parts and labor) for this repair */
  lineItems: RepairLineItem[]
  /** Work log timer sessions for this repair */
  workLogs: WorkLog[]
}

// ============================================================================
// Labor Service — predefined service catalog entry
// ============================================================================

/** A labor service from the predefined catalog */
export interface LaborService {
  id: string
  name: string
  description: string | null
  billingType: 'hourly' | 'fixed'
  defaultRate: number // cents/hour for hourly, fixed amount for fixed-rate
  isActive: boolean
}

// ============================================================================
// Line Item Input — creating/updating repair line items
// ============================================================================

/** Input for creating a part-based line item */
export interface CreatePartLineItemInput {
  /** Type of line item (always 'part' for this variant) */
  lineType: 'part'
  /** Part ID from the catalog */
  partId: string
  /** Human-readable description (snapshotted at creation) */
  description: string
  /** Quantity of parts used */
  quantity: number
  /** Unit price ex-tax in cents */
  unitPriceNet: number
  /** VAT rate reference ID */
  vatRateId: string
  /** Discount basis points (nullable = no discount) */
  discountPercent?: number | null
}

/** Input for creating a labor-based line item */
export interface CreateLaborLineItemInput {
  /** Type of line item (always 'labor' for this variant) */
  lineType: 'labor'
  /** Labor service ID from the catalog */
  laborServiceId: string
  /** Human-readable description (snapshotted at creation) */
  description: string
  /** Quantity (usually 1 for labor) */
  quantity: number
  /** Unit price ex-tax in cents */
  unitPriceNet: number
  /** VAT rate reference ID */
  vatRateId: string
  /** Discount basis points (nullable = no discount) */
  discountPercent?: number | null
  /** Minutes worked for billing purposes */
  minutesWorked?: number | null
  /** Worker's hourly rate snapshot at time of logging */
  hourlyRateSnapshot?: number | null
}

/** Union type for creating any line item on a repair */
export type CreateRepairLineItemInput = CreatePartLineItemInput | CreateLaborLineItemInput

/** Input for updating an existing repair line item */
export interface UpdateRepairLineItemInput {
  /** Quantity (for parts) */
  quantity?: number
  /** Unit price ex-tax in cents */
  unitPriceNet?: number
  /** Discount basis points */
  discountPercent?: number | null
  /** Minutes worked (for labor items) */
  minutesWorked?: number | null
  /** Hourly rate snapshot (for hourly labor items) */
  hourlyRateSnapshot?: number | null
}

// ============================================================================
// Worker Assignment — reassigning a repair to a different technician
// ============================================================================

/** Input for assigning or changing the assigned worker on a repair */
export interface AssignWorkerInput {
  /** Worker ID to assign (nullable to unassign) */
  assignedTo: string | null
}

// ============================================================================
// Payment Completion — atomic transaction at repair completion
// ============================================================================

/** A single payment method entry for split payments */
export interface RepairPaymentMethod {
  /** Payment method */
  method: 'cash' | 'card'
  /** Amount in cents to charge via this method */
  amount: number
}

/** Input for completing a repair with payment data (single or split) */
export interface CompleteRepairInput {
  /** Array of payment methods — single entry for single-payment, multiple for split */
  payments: RepairPaymentMethod[]
}

/** Result returned after successful repair completion */
export interface CompleteRepairResult {
  /** The updated repair record with completedAt set */
  repair: {
    id: string
    bicycleId: string
    assignedTo: string | null
    status: RepairStatus
    customerNotes: string | null
    internalNotes: string | null
    holdReason: HoldReason | null
    holdReasonNote: string | null
    plannedDate: number | null
    pickupDate: number | null
    completedAt: number | null
    createdAt: number
  }
  /** The linked sale record created for revenue attribution */
  sale: {
    id: string
    saleNumber: string
    customerId: string | null
    sourceType: 'direct_sale' | 'repair' | 'customer_order' | 'backorder'
    sourceId: string | null
    status: 'completed' | 'voided'
    subtotalNet: number
    vatTotal: number
    totalGross: number
  }
  /** All payments created for this completion */
  payments: Array<{
    id: string
    method: 'cash' | 'card' | 'bank_transfer'
    amount: number
  }>
  /** Stock movements created for parts used */
  stockMovements: Array<{
    id: string
    partId: string
    quantityDelta: number
    reason: string
    referenceType: string
    referenceId: string
  }>
}

/**
 * Repairs API client — Unit tests for getRepairsForWeek.
 */

import { describe, it, expect, vi, afterEach } from 'vitest'
import type { RepairDetailWithCustomer } from '../types.js'

// ---------------------------------------------------------------------------
// Mock fetch globally
// ---------------------------------------------------------------------------

const mockFetch = vi.fn<any>()

Object.defineProperty(globalThis, 'fetch', {
  value: mockFetch,
  writable: true,
})

vi.mock('../api.js', async (importOriginal) => {
  const actual = await importOriginal()
  return actual
})

// Need to re-import after mocking fetch
async function importApi() {
  // Clear module cache so mocks take effect
  vi.resetModules()
  Object.defineProperty(globalThis, 'fetch', { value: mockFetch })
  const mod = await import('../api.js')
  return mod
}

function createMockRepair(id: string, status: RepairDetailWithCustomer['status'], plannedDate: number | null): RepairDetailWithCustomer {
  return {
    id,
    assignedTo: null,
    status,
    customerNotes: null,
    internalNotes: null,
    holdReason: null,
    holdReasonNote: null,
    plannedDate,
    pickupDate: null,
    completedAt: null,
