/**
 * Supplier Registry — Central list of all active supplier adapters.
 */

import type { SupplierAdapter, SupplierAuthStatus } from './base.js'
import { dstAdapter } from './dst/adapter.js'
import { kruitboschAdapter } from './kruitbosch/adapter.js'
import { gransierAdapter } from './gransier/adapter.js'
import { readSyncStatus, type SyncStatusFile } from '../../services/sync-status-service.js'

// ============================================================================
// All registered suppliers
// ============================================================================

const allSuppliers: SupplierAdapter[] = [
  dstAdapter,
  kruitboschAdapter,
  gransierAdapter
]

/** Get only enabled suppliers (based on env credentials) */
export function getActiveSuppliers(): SupplierAdapter[] {
  return allSuppliers.filter(s => s.isEnabled())
}

/** Find a supplier by ID */
export function findSupplier(id: string): SupplierAdapter | undefined {
  return allSuppliers.find(s => s.id === id)
}

/** Get all suppliers with their enabled status, sync status, and auth info (for UI) */
export async function getSupplierList(): Promise<Array<{
  id: string
  name: string
  enabled: boolean
  lastSyncedAt?: string | null
  status?: 'ok' | 'stale' | 'failed'
  authStatus?: SupplierAuthStatus
}>> {
  const result = await Promise.all(
    allSuppliers.map(async (s) => {
      const syncStatus = await readSyncStatus(s.id)
      const freshness = computeFreshness(syncStatus)

      return {
        id: s.id,
        name: s.name,
        enabled: s.isEnabled(),
        lastSyncedAt: syncStatus?.lastSyncedAt ?? undefined,
        status: freshness,
        authStatus: s.getStatus()
      }
    })
  )

  return result
}

/** Compute freshness category from sync status */
function computeFreshness(syncStatus: SyncStatusFile | null): 'ok' | 'stale' | 'failed' {
  // Never synced or failed sync → stale (will show red)
  if (!syncStatus || !syncStatus.lastSyncedAt) {
    return syncStatus?.error ? 'failed' : 'stale'
  }

  const lastSync = new Date(syncStatus.lastSyncedAt)
  const now = new Date()
  const hoursSinceSync = (now.getTime() - lastSync.getTime()) / (1000 * 60 * 60)

  if (hoursSinceSync < 24) {
    return 'ok' // same day → green
  } else if (hoursSinceSync < 120) { // 5 days = 120 hours
    return 'stale' // >1 day but ≤5 days → yellow
  } else {
    return 'failed' // >5 days → red
  }
}

